package com.collabspace.websocket;
import com.collabspace.dto.MessageDtos.*; import com.collabspace.entity.User; import com.collabspace.repository.UserRepository; import com.collabspace.service.DirectMessageService; import lombok.RequiredArgsConstructor; import org.springframework.messaging.handler.annotation.*; import org.springframework.messaging.simp.SimpMessagingTemplate; import org.springframework.stereotype.Controller; import java.util.*;
@Controller @RequiredArgsConstructor public class DirectMessageWebSocketController { private final DirectMessageService service; private final UserRepository users; private final SimpMessagingTemplate broker; @MessageMapping("/dm.send") public void send(@Payload Map<String,String> p){ UUID userId=UUID.fromString(p.get("userId")); DirectMessageResponse m=service.send(userId,new SendDirectMessageRequest(p.get("content"))); User recipient=users.findById(userId).orElseThrow(); broker.convertAndSendToUser(recipient.getEmail(),"/queue/messages",m); } }